() => {
  const all = [...document.querySelectorAll('*')];
  const label = (txt) => all.filter(e => e.children.length === 0 && e.textContent.trim().startsWith(txt));
  const gEl = label('分组维度')[0];
  const mEl = label('聚合指标')[0];
  if (!gEl || !mEl) return { error: 'not found' };
  // climb to drop-zone containers (closest bordered boxes)
  const zone = (el) => {
    let n = el;
    for (let i = 0; i < 6 && n; i++) {
      const cs = getComputedStyle(n);
      if ((cs.borderStyle !== 'none' && parseInt(cs.borderWidth) > 0) || cs.border.includes('px')) {
        const r = n.getBoundingClientRect();
        if (r.height > 40) return n;
      }
      n = n.parentElement;
    }
    return null;
  };
  const gz = zone(gEl) || gEl.closest('div');
  const mz = zone(mEl) || mEl.closest('div');
  const gr = gz.getBoundingClientRect();
  const mr = mz.getBoundingClientRect();
  const gcs = getComputedStyle(gz);
  const overflow = (el) => { const c = getComputedStyle(el); return c.overflow + '/' + c.overflowX; };
  return {
    innerWidth: window.innerWidth,
    matchMedia_sm: window.matchMedia('(min-width: 640px)').matches,
    groupZone: { x: Math.round(gr.x), y: Math.round(gr.y), w: Math.round(gr.width), h: Math.round(gr.height), writingMode: gcs.writingMode },
    metricZone: { x: Math.round(mr.x), y: Math.round(mr.y), w: Math.round(mr.width), h: Math.round(mr.height) },
    stacked: Math.abs(gr.x - mr.x) < 4 && mr.y > gr.y,
    sideBySide: Math.abs(gr.y - mr.y) < 4 && mr.x > gr.x,
    groupClipped: gz.scrollWidth > gz.clientWidth + 1 || gz.scrollHeight > gz.clientHeight + 1,
    metricClipped: mz.scrollWidth > mz.clientWidth + 1 || mz.scrollHeight > mz.clientHeight + 1,
    groupOverflow: overflow(gz),
    metricOverflow: overflow(mz),
    rightEdgeInView: gr.right <= window.innerWidth + 1 && mr.right <= window.innerWidth + 1
  };
}

() => {
  const all = [...document.querySelectorAll('*')];
  const mEl = all.filter(e => e.children.length === 0 && e.textContent.trim().startsWith('聚合指标'))[0];
  let n = mEl;
  let zones = [];
  for (let i = 0; i < 8 && n; i++) {
    const r = n.getBoundingClientRect();
    const cs = getComputedStyle(n);
    zones.push({
      tag: n.tagName,
      cls: (n.className || '').toString().slice(0, 120),
      x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
      sh: n.scrollHeight, ch: n.clientHeight,
      maxH: cs.maxHeight, ovY: cs.overflowY
    });
    n = n.parentElement;
  }
  return zones;
}

() => {
  const all = [...document.querySelectorAll('*')];
  const grid = all.find(e => (e.className||'').toString().includes('grid-cols-1 sm:grid-cols-2'));
  grid.scrollIntoView({ block: 'start' });
  const r = grid.getBoundingClientRect();
  return { y: Math.round(r.y), h: Math.round(r.height), innerW: window.innerWidth };
}

() => {
  const doc = document.documentElement;
  const chips = [...document.querySelectorAll('*')].filter(e => e.children.length <= 3 && e.textContent.includes('本年投放金额') && e.textContent.includes('求和'));
  const chip = chips.sort((a,b)=>a.textContent.length-b.textContent.length)[0];
  let info = null;
  if (chip) {
    const r = chip.getBoundingClientRect();
    info = { x: Math.round(r.x), right: Math.round(r.right), w: Math.round(r.width), h: Math.round(r.height) };
  }
  const gChip = [...document.querySelectorAll('*')].filter(e => e.textContent.trim() === '机构名称 ×' || (e.textContent.includes('机构名称') && e.textContent.includes('×') && e.textContent.length < 12))[0];
  let gInfo = null;
  if (gChip) { const r = gChip.getBoundingClientRect(); gInfo = { x: Math.round(r.x), right: Math.round(r.right), w: Math.round(r.width) }; }
  return {
    innerWidth: window.innerWidth,
    docScrollW: doc.scrollWidth,
    bodyScrollW: document.body.scrollWidth,
    hOverflow: doc.scrollWidth > window.innerWidth,
    metricChip: info,
    dimChip: gInfo
  };
}

() => {
  const out = { sm_grid2: [], xl_grid12: [] };
  for (const sheet of document.styleSheets) {
    let rules;
    try { rules = sheet.cssRules; } catch (e) { continue; }
    for (const r of rules) {
      if (r.media) {
        const mediaText = r.media.mediaText;
        for (const inner of r.cssRules || []) {
          const t = inner.cssText || '';
          if (mediaText.includes('640px') && t.includes('grid-cols-2')) out.sm_grid2.push({ media: mediaText, css: t.slice(0, 140) });
          if (mediaText.includes('1280px') && t.includes('grid-cols-12')) out.xl_grid12.push({ media: mediaText, css: t.slice(0, 140) });
        }
      }
    }
  }
  return out;
}

() => {
  const found = [];
  for (const sheet of document.styleSheets) {
    let rules;
    try { rules = sheet.cssRules; } catch (e) { found.push({ err: 'cors', href: sheet.href }); continue; }
    const walk = (rs, depth) => {
      for (const r of rs) {
        if (r.media) {
          found.push({ media: r.media.mediaText.slice(0, 80), n: (r.cssRules||[]).length });
          if (depth < 3) walk(r.cssRules || [], depth + 1);
        }
      }
    };
    walk(rules, 0);
  }
  return { count: found.length, sample: found.slice(0, 20) };
}

() => {
  const sheets = [...document.styleSheets].map(s => ({ href: s.href, n: (() => { try { return s.cssRules.length; } catch (e) { return 'ERR'; } })() }));
  return { sheets, styleTags: document.querySelectorAll('style').length, links: [...document.querySelectorAll('link[rel=stylesheet]')].map(l => l.href) };
}

() => {
  const sheet = document.styleSheets[0];
  const texts = [...sheet.cssRules].map(r => r.cssText);
  const hits640 = texts.filter(t => t.includes('640'));
  const hits1280 = texts.filter(t => t.includes('1280'));
  const gridCols = texts.filter(t => t.includes('grid-cols-2') || t.includes('grid-cols-12')).slice(0, 6);
  return { total: texts.length, hits640: hits640.slice(0, 5), hits1280: hits1280.slice(0, 5), gridCols };
}

